function historyPagination({ page, pages, total, limit }) { if (!total) return ''; const first = (page - 1) * limit + 1, last = Math.min(page * limit, total); if (pages === 1) return `<nav class="lead-pagination" aria-label="Search history pagination"><p>Showing ${first}–${last} of ${total} searches</p></nav>`; const start = Math.max(1, Math.min(page - 2, pages - 4)), end = Math.min(pages, start + 4); return `<nav class="lead-pagination" aria-label="Search history pagination"><p>Showing ${first}–${last} of ${total} searches</p><div class="pagination-actions"><button class="button secondary" type="button" data-history-page="${page - 1}" ${page === 1 ? 'disabled' : ''}>Previous</button><div class="page-numbers" aria-label="Page numbers">${Array.from({ length: end - start + 1 }, (_, index) => { const number = start + index; return `<button class="button secondary ${number === page ? 'active' : ''}" type="button" data-history-page="${number}" ${number === page ? 'aria-current="page"' : ''}>${number}</button>`; }).join('')}</div><button class="button secondary" type="button" data-history-page="${page + 1}" ${page === pages ? 'disabled' : ''}>Next</button></div></nav>`; }
async function loadHistory() { const page = state.pages.history || 1, request = ++state.historyRequest, target = $('#history-results'); target.innerHTML = loading('Loading search history…'); try { let data = await api(`/api/search-history?${new URLSearchParams({ page, limit: 25 })}`); if (request !== state.historyRequest) return; if (!data.items.length && data.pagination.total && page > data.pagination.pages) { state.pages.history = data.pagination.pages; data = await api(`/api/search-history?${new URLSearchParams({ page: state.pages.history, limit: 25 })}`); if (request !== state.historyRequest) return; } state.historyPages = data.pagination.pages; $('#history-count').textContent = plural(data.pagination.total, 'search'); target.innerHTML = data.items.length ? `<table class="history-table"><thead><tr><th>Category</th><th>Location</th><th>Requested</th><th>Found</th></tr></thead><tbody>${data.items.map(x => `<tr><td>${escape(x.category)}</td><td>${escape(x.location)}</td><td>${x.requestedCount}</td><td>${x.foundCount}</td></tr>`).join('')}</tbody></table>${historyPagination(data.pagination)}` : empty('No searches yet', 'Completed searches appear here.'); } catch (error) { if (request === state.historyRequest) target.innerHTML = empty('Unable to load history', message(error.message)); } }
function mailboxPagination({ page, pages, total, limit }) { const first = total ? (page - 1) * limit + 1 : 0, last = Math.min(page * limit, total); return `<nav class="pagination mailbox-pagination" aria-label="Mailbox pagination"><span class="mailbox-page-summary">${total ? `Showing ${first}–${last} of ${total} · Page ${page} of ${pages}` : '0 emails · Page 1 of 1'}</span><div class="mailbox-page-actions"><button class="button secondary" type="button" data-mailbox-page="${page - 1}" ${page === 1 ? 'disabled' : ''}>Previous</button><button class="button secondary" type="button" data-mailbox-page="${page + 1}" ${page === pages ? 'disabled' : ''}>Next</button></div></nav>`; }
function updateMailboxSelection() { const count = state.mailboxSelected.size; const label = $('#mailbox-selected-count'); if (label) label.textContent = `${count} selected`; const all = $('#mailbox-select-all'); if (all) all.checked = document.querySelectorAll('.mail-select').length > 0 && [...document.querySelectorAll('.mail-select')].every(box => box.checked); ['mailbox-delete-selected', 'mailbox-mark-not-useful', 'mailbox-restore-selected', 'mailbox-permanent-delete-selected'].forEach(id => { const button = $(`#${id}`); if (button) button.hidden = !count; }); }
function mailboxNotUsefulDetails(summary) { const details = []; if (summary.discardedLeads) details.push(`${plural(summary.discardedLeads)} already marked as Not Useful and will not be changed.`); if (summary.noAssociatedLead) details.push(`${plural(summary.noAssociatedLead, 'selected email')} has no associated lead and will not be changed.`); return details.map(detail => `<p>${escape(detail)}</p>`).join(''); }
function showMailboxNotUsefulConfirmation(summary) { state.mailboxNotUsefulSummary = summary; const eligible = summary.eligibleLeads; if (!eligible) { const title = summary.associatedLeads === 1 && summary.discardedLeads === 1 ? 'Lead already marked Not Useful' : 'No leads need changes'; const message = summary.discardedLeads ? `All ${plural(summary.associatedLeads)} are already marked as Not Useful. No changes are required.` : 'None of the selected emails has an associated lead. No changes are required.'; return openModal(`<h2>${title}</h2><p>${escape(message)}</p>${mailboxNotUsefulDetails(summary)}<div class="modal-actions"><button class="button secondary" type="button" data-close-modal>Close</button></div>`); }
  const title = eligible === 1 ? 'Mark lead as Not Useful?' : `Mark ${eligible} leads as Not Useful?`;
  return openModal(`<h2>${title}</h2><p>${eligible === 1 ? 'This lead will be marked as Not Useful and removed from Saved Leads.' : `${plural(eligible)} will be marked as Not Useful and removed from Saved Leads.`}</p>${mailboxNotUsefulDetails(summary)}<div class="modal-actions"><button class="button secondary" type="button" data-close-modal>Cancel</button><button class="button danger" type="button" data-confirm-mailbox-not-useful>Mark ${eligible === 1 ? 'Not Useful' : `${eligible} Leads Not Useful`}</button></div>`); }
async function checkMailboxNotUseful() { if (state.mailboxNotUsefulChecking || state.mailboxNotUsefulUpdating || !state.mailboxSelected.size) return; state.mailboxNotUsefulChecking = true; state.mailboxNotUsefulSummary = null; state.mailboxNotUsefulTarget = [...state.mailboxSelected]; const ids = state.mailboxNotUsefulTarget; openModal(`<h2>Checking selected leads…</h2><p>Please wait while we verify the current lead status.</p>${loading('Checking selected leads…')}`); try { const summary = await api('/api/mailbox/messages/not-useful/check', { method: 'POST', body: JSON.stringify({ ids }) }); if (state.mailboxNotUsefulTarget === ids) showMailboxNotUsefulConfirmation(summary); } catch { if (state.mailboxNotUsefulTarget !== ids) return; state.mailboxNotUsefulTarget = null; $('#outreach-modal-content').innerHTML = `<h2>Unable to verify the selected leads</h2><p>Unable to verify the selected leads. No changes were made.</p><div class="modal-actions"><button class="button secondary" type="button" data-close-modal>Cancel</button><button class="button primary" type="button" data-retry-mailbox-not-useful>Try Again</button></div>`; } finally { state.mailboxNotUsefulChecking = false; } }
async function markMailboxNotUseful(button) { const ids = state.mailboxNotUsefulTarget; if (state.mailboxNotUsefulUpdating || !state.mailboxNotUsefulSummary || !ids?.length || !setButtonLoading(button, true, 'Marking leads as Not Useful…')) return; state.mailboxNotUsefulUpdating = true; try { const result = await api('/api/mailbox/messages/not-useful', { method: 'POST', body: JSON.stringify({ ids, confirmation: 'NOT_USEFUL' }) }); state.mailboxSelected.clear(); state.mailboxNotUsefulSummary = null; state.mailboxNotUsefulTarget = null; $('#outreach-modal').close(); toast(result.markedLeads ? `${plural(result.markedLeads)} marked Not Useful` : 'Selected leads were already marked Not Useful'); await loadMailbox(); } catch (error) { toast(message(error.message)); await loadMailbox(); } finally { state.mailboxNotUsefulUpdating = false; setButtonLoading(button, false); } }
async function loadMailboxCounts() { const request = ++state.mailboxCountsRequest; try { const counts = await api('/api/mailbox/counts'); if (request !== state.mailboxCountsRequest || state.view !== 'mailbox') return; $('#mailbox-inbox-count').textContent = counts.inbox; $('#mailbox-sent-count').textContent = counts.sent; $('#mailbox-trash-count').textContent = counts.trash; } catch { /* Existing mailbox data and counts remain intact if this lightweight request fails. */ } }
async function loadMailbox() { const box = state.mailboxBox, page = state.mailboxPage, search = $('#mailbox-search').value.trim(), request = ++state.mailboxRequest, target = $('#mailbox-results'); state.mailboxLoading = true; target.innerHTML = loading('Loading mail…'); try { let data = await api(`/api/mailbox/${box}?${new URLSearchParams({ page, limit: 25, search })}`); if (request !== state.mailboxRequest) return; if (!data.items.length && data.pagination.total && page > data.pagination.pages) { state.mailboxPage = data.pagination.pages; data = await api(`/api/mailbox/${box}?${new URLSearchParams({ page: state.mailboxPage, limit: 25, search })}`); if (request !== state.mailboxRequest) return; } const visible = new Set(data.items.map(item => item._id)); state.mailboxSelected = new Set([...state.mailboxSelected].filter(id => visible.has(id))); if (box === 'inbox') $('#mailbox-unread').textContent = data.unreadCount ? `Unread ${data.unreadCount}` : ''; const controls = box !== 'trash' ? `<div class="mailbox-selection"><label><input id="mailbox-select-all" type="checkbox" aria-label="Select all emails on this page"> Select page</label><span id="mailbox-selected-count">${state.mailboxSelected.size} selected</span><div class="mailbox-selection-actions"><button id="mailbox-delete-selected" class="button danger" type="button" ${state.mailboxSelected.size ? '' : 'hidden'}>Delete Selected</button><div class="mailbox-selection-danger"><span>Lead status</span><button id="mailbox-mark-not-useful" class="button secondary danger" type="button" ${state.mailboxSelected.size ? '' : 'hidden'}>Mark Not Useful</button></div></div></div>` : `<div class="mailbox-selection mailbox-trash-selection"><label><input id="mailbox-select-all" type="checkbox" aria-label="Select all Trash emails on this page"> Select all</label><span id="mailbox-selected-count">${state.mailboxSelected.size} selected</span><button id="mailbox-restore-selected" class="button secondary" type="button" ${state.mailboxSelected.size ? '' : 'hidden'}>Restore</button><div class="mailbox-selection-danger"><span>Lead status</span><button id="mailbox-mark-not-useful" class="button secondary danger" type="button" ${state.mailboxSelected.size ? '' : 'hidden'}>Mark Not Useful</button></div><button id="mailbox-permanent-delete-selected" class="button danger" type="button" ${state.mailboxSelected.size ? '' : 'hidden'}>Delete permanently</button></div>`; target.innerHTML = `${controls}${data.items.length ? `<div class="mail-list">${data.items.map(item => `<div class="mail-row ${item.readAt === null && item.box !== 'sent' ? 'unread' : ''}"><input class="mail-select" type="checkbox" data-id="${item._id}" aria-label="Select ${escape(item.subject || 'email')}" ${state.mailboxSelected.has(item._id) ? 'checked' : ''}><button class="mail-open" type="button" data-open-mail="${escape(item.conversationId)}" ${box === 'trash' ? 'data-open-trash-mail' : ''}><span class="mail-dot" aria-label="${item.readAt === null ? 'Unread' : 'Read'}"></span><span class="mail-sender">${escape(item.from)}</span><span class="mail-subject">${escape(item.subject || '(No subject)')}${item.source === 'campaign' ? ' <em class="mail-source">Campaign</em>' : ''}${item.leadNotUseful ? ' <em class="mail-not-useful">Not Useful</em>' : ''}</span><span class="mail-snippet">${escape(item.snippet || item.text || '')}</span><time>${escape(new Date(item.receivedAt || item.sentAt || item.deletedAt).toLocaleDateString())}</time></button></div>`).join('')}</div>` : empty(box === 'sent' ? 'No sent emails yet' : box === 'trash' ? 'Trash is empty' : 'No messages yet', box === 'sent' ? 'Direct and campaign emails appear here.' : 'New incoming emails will appear here.')}${mailboxPagination(data.pagination)}`; updateMailboxSelection(); } catch (error) { if (request === state.mailboxRequest) target.innerHTML = `<div class="mailbox-error">${empty('Unable to load mail', message(error.message))}<button class="button secondary" type="button" data-retry-mailbox>Retry</button></div>`; } finally { if (request === state.mailboxRequest) state.mailboxLoading = false; } }
async function openMailConversation(id, trash = false) { if (state.openingConversation === id) return; const request = ++state.conversationRequest; state.openingConversation = id; openModal(`<section class="mail-detail">${loading('Opening conversation…')}</section>`); try { const data = await api(`/api/mailbox/conversations/${encodeURIComponent(id)}${trash ? '?trash=true' : ''}`); if (request !== state.conversationRequest) return; const messages = data.items.map(item => `<article class="mail-message ${item.box === 'sent' ? 'mail-message-sent' : 'mail-message-inbound'}"><header><div><b>${escape(item.box === 'sent' ? 'You' : item.from)}${item.source === 'campaign' ? ' <span class="mail-source">Campaign</span>' : ''}</b><span class="mail-recipient">${escape(item.box === 'sent' ? `To ${item.to?.join(', ') || 'recipient'}` : 'External sender')}</span></div><time datetime="${escape(new Date(item.date).toISOString())}">${escape(new Date(item.date).toLocaleString())}</time></header><pre>${escape(item.text || 'This email has no plain-text content.')}</pre></article>`).join(''); const latest = data.items.at(-1) || {}, latestInbound = [...data.items].reverse().find(item => item.box === 'inbox'); const reply = !trash && latestInbound ? `<div class="mail-detail-actions"><button class="button primary" type="button" data-mail-reply="${escape(id)}" data-mail-to="${escape(latestInbound.fromEmail || '')}" data-mail-subject="${escape(latestInbound.subject || '')}">Reply</button></div>` : ''; $('#outreach-modal-content').innerHTML = `<section class="mail-detail"><header class="mail-detail-heading"><p class="eyebrow">${trash ? 'Trash conversation' : 'Conversation'}</p><h2>${escape(latest.subject || 'Email')}</h2><p>${data.items.length} message${data.items.length === 1 ? '' : 's'}</p></header><div class="mail-thread">${messages}</div>${reply}${trash ? '<p class="mail-trash-note">This conversation remains in Trash until you restore or permanently delete its messages.</p>' : ''}</section>`; if (!trash) loadMailbox(); } catch (error) { if (request === state.conversationRequest) $('#outreach-modal-content').innerHTML = `<section class="mail-detail"><div class="mailbox-error">${empty('Unable to open conversation', message(error.message))}<button class="button secondary" type="button" data-retry-conversation="${escape(id)}" ${trash ? 'data-retry-trash-conversation' : ''}>Retry</button></div></section>`; } finally { if (request === state.conversationRequest) state.openingConversation = null; } }
function emailProviderOptions() { return '<option value="resend">Resend</option><option value="brevo">Brevo</option>'; }
function mailboxComposer(replyId = '', values = {}) { const isReply = Boolean(replyId); openModal(`<section class="mail-compose"><header class="mail-compose-heading"><p class="eyebrow">${isReply ? 'Conversation reply' : 'New email'}</p><h2>${isReply ? 'Reply' : 'Compose message'}</h2>${isReply ? '<p>Your recipient and subject are set from this conversation.</p>' : ''}</header><div class="modal-grid">${isReply ? '' : `<label>Provider<select id="mail-email-provider" aria-label="Email provider">${emailProviderOptions()}</select></label>`}<label>To<input id="mail-to" inputmode="email" maxlength="254" value="${escape(values.to || '')}" required ${isReply ? 'readonly' : ''}></label><label>Cc<input id="mail-cc" inputmode="email" maxlength="254" ${isReply ? 'readonly' : ''}></label><label>Bcc<input id="mail-bcc" inputmode="email" maxlength="254" ${isReply ? 'readonly' : ''}></label><label>Subject<input id="mail-subject" maxlength="500" value="${escape(values.subject || '')}" required ${isReply ? 'readonly' : ''}></label><label class="mail-message-field">Message<textarea id="mail-text" maxlength="20000" required autofocus></textarea></label></div><div class="modal-actions"><button class="button secondary" type="button" data-close-modal>Cancel</button><button class="button primary" data-mail-send="${escape(replyId)}">Send</button></div></section>`); }
function closeMobileNav(restoreFocus = false) { const nav = $('#mobile-nav'), toggle = $('#menu-toggle'); if (!nav.classList.contains('open')) return; nav.classList.remove('open'); nav.inert = true; nav.setAttribute('aria-hidden', 'true'); toggle.setAttribute('aria-expanded', 'false'); toggle.setAttribute('aria-label', 'Open navigation menu'); if (restoreFocus) toggle.focus(); }
function setView(view) { state.view = ['find', 'saved', 'discarded', 'campaigns', 'mailbox', 'templates', 'history', 'settings'].includes(view) ? view : 'find'; document.querySelectorAll('.view').forEach(e => { e.hidden = e.id !== `view-${state.view}`; }); document.querySelectorAll('[data-view]').forEach(e => e.classList.toggle('active', e.dataset.view === state.view)); closeMobileNav(); if (state.view === 'saved' || state.view === 'discarded') { loadLeads(state.view); if (state.view === 'saved') populateCampaignFilter(); } if (state.view === 'history') loadHistory(); if (state.view === 'campaigns') loadCampaigns(); if (state.view === 'templates') loadTemplates(); if (state.view === 'mailbox') { loadMailbox(); loadMailboxCounts(); } }
async function finishJob(job) { if (job.jobId && state.jobId !== job.jobId) return; stopPolling(); state.cancelling = false; clearActiveJob(); $('#job-progress').hidden = true; if (job.status === 'cancelled') { state.job = null; state.jobId = null; state.selected.clear(); setDiscoveryRunning(false); $('#new-results').innerHTML = empty('No new usable leads yet', 'Run a discovery search to begin.'); $('#bulk-actions').hidden = true; $('#results-summary').textContent = 'Search cancelled. No results were kept.'; toast('Search cancelled'); return; } state.job = job; state.jobId = job.jobId; toast(job.status === 'completed' ? 'Discovery complete' : message(job.error)); await loadCurrentLeads(); }
async function poll(generation = state.pollGeneration) { if (!state.jobId || state.pollInFlight || generation !== state.pollGeneration) return; state.pollInFlight = true; const id = state.jobId; try { const job = await api(`/api/discovery/jobs/${id}`); if (state.jobId !== id || generation !== state.pollGeneration) return; state.job = job; if (terminalStates.has(job.status)) await finishJob(job); else setProgress(job); } catch (e) { if (state.jobId === id && generation === state.pollGeneration) toast(`Unable to refresh search progress: ${message(e.message)}`); } finally { state.pollInFlight = false; } }
$('#discovery-form').addEventListener('submit', async e => { e.preventDefault(); if (state.jobId) return; const button = $('#find-leads-button'); if (!setButtonLoading(button, true, 'Searching…')) return; const data = Object.fromEntries(new FormData(e.currentTarget)); try { const job = await api('/api/discovery/jobs', { method: 'POST', body: JSON.stringify(data) }); setButtonLoading(button, false); state.newLeadCount = 0; state.jobId = job.jobId; state.job = job; localStorage.setItem(ACTIVE_JOB_KEY, job.jobId); setDiscoveryRunning(true); $('#job-progress').hidden = false; setProgress({ ...job, requested: Number(data.requestedCount), found: 0, duplicates: 0, rejected: 0 }); $('#new-results').innerHTML = loading('Searching for businesses…'); const generation = state.pollGeneration; await poll(generation); if (state.jobId && !terminalStates.has(state.job?.status) && generation === state.pollGeneration) state.poll = setInterval(() => poll(generation), 2500); } catch (err) { toast(message(err.message)); } finally { setButtonLoading(button, false); } });
$('#cancel-job').addEventListener('click', async e => { if (!state.jobId || state.cancelling) return; const button = e.currentTarget, id = state.jobId; state.cancelling = true; stopPolling(); setDiscoveryRunning(true, true); if (!setButtonLoading(button, true, 'Cancelling…')) return; try { const job = await api(`/api/discovery/jobs/${id}/cancel`, { method: 'POST' }); if (state.jobId !== id) return; await finishJob(job); } catch (e) { if (state.jobId !== id) return; state.cancelling = false; setDiscoveryRunning(true); const generation = state.pollGeneration; state.poll = setInterval(() => poll(generation), 2500); toast(`Cancellation was not confirmed: ${message(e.message)}`); } finally { setButtonLoading(button, false); if (!state.jobId) setDiscoveryRunning(false); } });
async function act(ids, action, button) { if (!setButtonLoading(button, true, action === 'saved' ? 'Saving…' : action === 'discarded' ? 'Updating…' : 'Deleting…')) return; try { if (ids.length === 1 && action !== 'delete') await api(`/api/leads/${ids[0]}/status`, { method: 'PATCH', body: JSON.stringify({ status: action }) }); else if (ids.length === 1 && action === 'delete') await api(`/api/leads/${ids[0]}`, { method: 'DELETE' }); else await api('/api/leads/bulk', { method: 'POST', body: JSON.stringify({ ids, action }) }); ids.forEach(id => state.selected.delete(id)); toast(action === 'saved' ? 'Lead saved' : action === 'discarded' ? 'Lead marked Not Useful' : 'Lead(s) cleared'); await loadCurrentLeads(); } catch (e) { toast(message(e.message)); } finally { setButtonLoading(button, false); } }
document.addEventListener('click', async e => { const exportLink = e.target.closest('[id$="-export"]'); if (exportLink) { e.preventDefault(); const view = exportLink.id.replace('-export', ''); if (view === 'new' && (!state.jobId || !state.newLeadCount)) { toast('No leads available to export.'); return; } const query = view === 'new' ? `status=new&searchJobId=${encodeURIComponent(state.jobId)}` : new URLSearchParams({ status: view, ...(state.filters[view] || {}) }).toString(); window.location.href = `/api/leads/export?${query}`; return; } const clear = e.target.closest('[data-clear-filter]'); if (clear) { const view = clear.dataset.clearFilter; $(`#${view}-search`).value = ''; $(`#${view}-from`).value = ''; $(`#${view}-to`).value = ''; if (view === 'saved') { $('#saved-channel').value = 'all'; $('#saved-communication-status').value = 'all'; $('#saved-campaign').value = ''; state.leadTab = 'all'; document.querySelectorAll('[data-lead-tab]').forEach(button => { const selected = button.dataset.leadTab === 'all'; button.classList.toggle('active', selected); button.setAttribute('aria-selected', String(selected)); button.tabIndex = selected ? 0 : -1; }); state.savedSelected.clear(); state.savedExcluded.clear(); state.savedSelectAll = false; } state.pages[view] = 1; loadLeads(view); return; } const historyPage = e.target.closest('[data-history-page]'); if (historyPage) { const page = Number(historyPage.dataset.historyPage); if (!Number.isInteger(page) || page < 1 || page > state.historyPages) return; state.pages.history = page; return loadHistory(); } const page = e.target.closest('[data-lead-page]'); if (page) { state.pages.saved = Number(page.dataset.leadPage); return loadLeads('saved'); } const discardedPage = e.target.closest('[data-discarded-page]'); if (discardedPage) { const page = Number(discardedPage.dataset.discardedPage); if (!Number.isInteger(page) || page < 1) return; state.pages.discarded = page; return loadLeads('discarded'); } const nav = e.target.closest('[data-view]'); if (nav) { e.preventDefault(); location.hash = nav.dataset.view; return; } const bulk = e.target.closest('[data-bulk]'); if (bulk) return act([...state.selected], bulk.dataset.bulk, bulk); const remove = e.target.closest('[data-delete-id]'); if (remove) return act([remove.dataset.deleteId], 'delete', remove); const action = e.target.closest('[data-status]'); if (action) { if (state.view === 'find') return act([action.dataset.id], action.dataset.status, action); if (!setButtonLoading(action, true, 'Restoring…')) return; try { await api(`/api/leads/${action.dataset.id}/status`, { method: 'PATCH', body: JSON.stringify({ status: 'new' }) }); await loadLeads(state.view); } catch (err) { toast(message(err.message)); } finally { setButtonLoading(action, false); } } });
document.addEventListener('change', e => { if (e.target.id === 'select-all') { document.querySelectorAll('.lead-select').forEach(x => { x.checked = e.target.checked; if (e.target.checked) state.selected.add(x.dataset.id); else state.selected.delete(x.dataset.id); }); updateBulk(); } if (e.target.matches('.lead-select')) { if (e.target.checked) state.selected.add(e.target.dataset.id); else state.selected.delete(e.target.dataset.id); updateBulk(); } if (e.target.id === 'mailbox-select-all') { document.querySelectorAll('.mail-select').forEach(box => { box.checked = e.target.checked; if (e.target.checked) state.mailboxSelected.add(box.dataset.id); else state.mailboxSelected.delete(box.dataset.id); }); updateMailboxSelection(); } if (e.target.matches('.mail-select')) { if (e.target.checked) state.mailboxSelected.add(e.target.dataset.id); else state.mailboxSelected.delete(e.target.dataset.id); updateMailboxSelection(); } });
let mailboxSearchTimer; $('#mailbox-search').addEventListener('input', () => { clearTimeout(mailboxSearchTimer); mailboxSearchTimer = setTimeout(() => { state.mailboxPage = 1; state.mailboxSelected.clear(); loadMailbox(); }, 250); });
document.addEventListener('submit', e => { const form = e.target.closest('[data-search-form]'); if (!form) return; e.preventDefault(); state.pages[form.dataset.searchForm] = 1; loadLeads(form.dataset.searchForm); });
function deletionPayload(includeConfirmation = false) { return { status: $('#delete-status').value, scope: $('#delete-scope').value, from: $('#delete-from').value, to: $('#delete-to').value, ...(includeConfirmation ? { confirmation: $('#delete-confirmation').value } : {}) }; }
function updateDeletionControls() { const custom = $('#delete-scope').value === 'custom'; $('#delete-from').disabled = !custom; $('#delete-to').disabled = !custom; const status = $('#delete-status').value; $('#delete-date-help').textContent = status === 'saved' ? 'Dates use the time each lead was saved.' : status === 'discarded' ? 'Dates use the time each lead was marked Not Useful.' : 'Dates use discovery time for All and New leads.'; $('#delete-submit').disabled = $('#delete-confirmation').value !== 'DELETE'; }
function showDeletionPreview(result) { const breakdown = result.breakdown || {}; $('#deletion-result').textContent = `${plural(result.count)} match the current filters.`; $('#delete-total').textContent = breakdown.total ?? result.count; $('#delete-new').textContent = breakdown.new ?? '—'; $('#delete-saved').textContent = breakdown.saved ?? '—'; $('#delete-discarded').textContent = breakdown.discarded ?? '—'; }
$('#delete-status').addEventListener('change', updateDeletionControls); $('#delete-scope').addEventListener('change', updateDeletionControls); $('#delete-confirmation').addEventListener('input', updateDeletionControls); updateDeletionControls();
$('#deletion-count').addEventListener('click', async e => { const button = e.currentTarget; if (!setButtonLoading(button, true, 'Checking…')) return; try { showDeletionPreview(await api('/api/settings/lead-deletion/count', { method: 'POST', body: JSON.stringify(deletionPayload()) })); } catch (e) { toast(message(e.message)); } finally { setButtonLoading(button, false); } });
$('#deletion-form').addEventListener('submit', async e => { e.preventDefault(); if ($('#delete-confirmation').value !== 'DELETE') return; const button = $('#delete-submit'); if (!setButtonLoading(button, true, 'Deleting…')) return; try { const result = await api('/api/settings/lead-deletion', { method: 'POST', body: JSON.stringify(deletionPayload(true)) }); $('#delete-confirmation').value = ''; updateDeletionControls(); $('#deletion-result').textContent = `${plural(result.deleted)} permanently deleted.`; ['delete-total', 'delete-new', 'delete-saved', 'delete-discarded'].forEach(id => { $(`#${id}`).textContent = '—'; }); toast('Matching leads permanently deleted'); if (state.view === 'find') loadCurrentLeads(); } catch (err) { toast(message(err.message)); } finally { setButtonLoading(button, false); updateDeletionControls(); } });
$('#menu-toggle').addEventListener('click', e => { const nav = $('#mobile-nav'), opening = !nav.classList.contains('open'); nav.classList.toggle('open', opening); nav.inert = !opening; nav.setAttribute('aria-hidden', String(!opening)); e.currentTarget.setAttribute('aria-expanded', String(opening)); e.currentTarget.setAttribute('aria-label', opening ? 'Close navigation menu' : 'Open navigation menu'); if (opening) nav.querySelector('a')?.focus(); }); document.addEventListener('keydown', e => { if (e.key === 'Escape') closeMobileNav(true); }); window.addEventListener('hashchange', () => setView(location.hash.slice(1) || 'find')); setView(location.hash.slice(1) || 'find');
(async () => { try { const current = await api('/api/discovery/current'); if (!current.job) return; state.job = current.job; state.jobId = current.job.jobId; if (!terminalStates.has(current.job.status)) { localStorage.setItem(ACTIVE_JOB_KEY, state.jobId); setDiscoveryRunning(true); $('#job-progress').hidden = false; setProgress(current.job); $('#new-results').innerHTML = loading('Searching for businesses…'); const generation = state.pollGeneration; await poll(generation); if (state.jobId && !terminalStates.has(state.job?.status) && generation === state.pollGeneration) state.poll = setInterval(() => poll(generation), 2500); } else { clearActiveJob(); await loadCurrentLeads(); } } catch { const remembered = localStorage.getItem(ACTIVE_JOB_KEY); if (remembered) { state.jobId = remembered; setDiscoveryRunning(true); $('#job-progress').hidden = false; setProgress({ status: 'running' }); const generation = state.pollGeneration; state.poll = setInterval(() => poll(generation), 2500); } } })();

function emailStatus(item) { return item ? item.status === 'sent' ? 'Sent' : item.status === 'failed' ? 'Failed' : item.status === 'skipped' ? 'Skipped' : 'Pending' : 'Not Sent'; }
function whatsappStatus(item) { const reason = item?.status === 'skipped' ? skipReasonLabel(item.skipReason) : ''; return item ? item.status === 'manual_sent' ? 'Manual Sent' : item.status === 'skipped' ? `Skipped${reason ? ` · ${reason}` : ''}` : 'Pending' : 'Not Sent'; }
function campaignProgress(c) { const total = c.emailCount || 0, sent = c.emailSentCount || 0, failed = c.emailFailedCount || 0, pending = c.emailPendingCount || 0, batches = Math.max(1, Math.ceil(total / 100)); if (!c.channels.includes('email') || !total) return ''; return `<div class="campaign-progress"><div class="progress-label"><b>Email delivery</b><span>${sent}/${total} sent</span></div><div class="delivery-bar" aria-label="Email delivery: ${sent} sent, ${failed} failed, ${pending} pending"><i style="width:${sent / total * 100}%"></i><em style="width:${failed / total * 100}%"></em></div><small>Batch ${c.currentBatch || 0} of ${batches} · ${c.currentBatchProcessed || 0}/${c.currentBatchSize || 0} processed</small></div>`; }
function campaignMetrics(c) { const hasEmail = c.channels.includes('email'), hasWhatsApp = c.channels.includes('whatsapp'); return `<div class="campaign-metrics">${hasEmail ? `<span><b>${c.emailCount || 0}</b>Email recipients</span><span><b>${c.emailSentCount || 0}</b>Email sent</span><span class="metric-failed"><b>${c.emailFailedCount || 0}</b>Email failed</span><span><b>${c.emailPendingCount || 0}</b>Email pending</span>` : ''}${hasWhatsApp ? `<span><b>${c.whatsappCount || 0}</b>WhatsApp recipients</span><span><b>${c.whatsappSentCount || 0}</b>WhatsApp sent</span><span><b>${c.whatsappPendingCount || 0}</b>WhatsApp ready</span><span><b>${c.whatsappSkippedCount || 0}</b>WhatsApp skipped</span>` : ''}</div>`; }
async function loadTemplates() { $('#template-results').innerHTML = loading('Loading templates…'); try { state.templates = (await api('/api/templates')).items; $('#template-results').innerHTML = state.templates.length ? `<div class="template-list">${state.templates.map(t => `<article class="outreach-card"><span class="status-badge">${escape(t.type)}</span><h2>${escape(t.name)}</h2><p>${t.type === 'email' ? `Subject: ${escape(t.subject)}` : escape(t.body.slice(0, 160))}</p><div class="actions"><button class="button secondary" data-edit-template="${t._id}">Edit</button><button class="button secondary" data-duplicate-template="${t._id}">Duplicate</button><button class="button danger" data-delete-template="${t._id}">Delete</button></div></article>`).join('')}</div>` : empty('No templates yet', 'Create your first email or WhatsApp template.'); } catch (e) { $('#template-results').innerHTML = empty('Unable to load templates', message(e.message)); } }
async function loadCampaigns() { $('#campaign-results').innerHTML = loading('Loading campaigns…'); try { const items = (await api('/api/campaigns')).items; $('#campaign-results').innerHTML = items.length ? `<div class="campaign-list">${items.map(c => `<article class="campaign-card"><header><div><h2 title="${escape(c.name)}">${escape(c.name)}</h2><span class="status-badge ${escape(c.status)}">${escape(c.status)}</span><span class="channel-indicators">${c.channels.includes('email') ? '✉ Email' : ''} ${c.channels.includes('whatsapp') ? '◉ WhatsApp' : ''}</span></div><div class="campaign-actions"><button class="button secondary" data-open-campaign-detail="${c._id}">Open campaign</button><button class="button secondary danger" data-delete-campaign="${c._id}" data-has-outreach="${(c.sentCount || c.failedCount) > 0}">Delete</button></div></header>${campaignMetrics(c)}${campaignProgress(c)}${c.emailFailedCount ? `<p class="failure-callout">${c.emailFailedCount} email failure${c.emailFailedCount === 1 ? '' : 's'} need attention.</p>` : ''}</article>`).join('')}</div>` : empty('No campaigns yet', 'Create a campaign from Lead Management.'); } catch (e) { $('#campaign-results').innerHTML = empty('Unable to load campaigns', message(e.message)); } }
function parseCsv(text) { const rows = []; let row = [], cell = '', quoted = false; for (let i = 0; i < text.length; i += 1) { const char = text[i]; if (char === '"') { if (quoted && text[i + 1] === '"') { cell += char; i += 1; } else quoted = !quoted; } else if (char === ',' && !quoted) { row.push(cell); cell = ''; } else if ((char === '\n' || char === '\r') && !quoted) { if (char === '\r' && text[i + 1] === '\n') i += 1; row.push(cell); if (row.some(value => value.trim())) rows.push(row); row = []; cell = ''; } else cell += char; } if (quoted) throw new Error('CSV has an unclosed quoted value.'); row.push(cell); if (row.some(value => value.trim())) rows.push(row); if (rows.length < 2) throw new Error('CSV must include a header and at least one row.'); const headers = rows.shift().map(value => value.trim().toLowerCase()); if (headers.some((value, index) => !value || headers.indexOf(value) !== index)) throw new Error('CSV headers must be unique.'); return rows.map(values => Object.fromEntries(headers.map((header, index) => [header, values[index] || '']))); }
function csvImportModal() { return `<h2>Import CSV</h2><p>Preview a CSV before adding leads or selecting existing records for the normal Lead Management actions.</p><div class="csv-mode"><button class="button primary" type="button" data-csv-mode="new">Add New Leads</button><button class="button secondary" type="button" data-csv-mode="existing">Existing Leads / Bulk Action</button></div><div class="csv-template"><button class="button secondary" type="button" data-csv-template>Download Template</button></div><div class="csv-upload"><label for="csv-file"><b>Upload CSV</b><span>Drag and drop or choose a file</span><small>Maximum 500 rows</small><input id="csv-file" type="file" accept=".csv,text/csv"></label></div><p class="csv-help">New leads require <b>business_name, website, email, country, category</b>. Existing leads require <b>business_name</b>; optional <b>id</b> and website improve matching.</p><div id="csv-preview" aria-live="polite"></div><div class="modal-actions"><button class="button secondary" type="button" data-close-modal>Cancel</button></div>`; }
// Existing Not Useful matches now use the clearer FOUND IN NOT USEFUL status (formerly Already Not Useful).
function csvStatusLabel(status) { return ({ found_in_lead_management: 'FOUND IN LEAD MANAGEMENT', found_in_not_useful: 'FOUND IN NOT USEFUL', found_in_both: 'FOUND IN BOTH', multiple_matches: 'MULTIPLE MATCHES / REVIEW REQUIRED', not_found: 'NOT FOUND', invalid: 'INVALID' })[status] || status.replaceAll('_', ' ').toUpperCase(); }
function csvMatchedNames(leads) { return (leads || []).map(lead => `${escape(lead.businessName)}${lead.domain ? ` <small>${escape(lead.domain)}</small>` : ''}`).join(', ') || '—'; }
function csvMatchedSavedLeadIds(preview) {
  return [...new Set(preview.rows
    .filter(row => ['found_in_lead_management', 'found_in_both'].includes(row.status))
    .map(row => row.selectedLeadId)
    .filter(Boolean))];
}
function replaceSavedLeadSelection(ids) {
  state.savedSelected.clear();
  state.savedExcluded.clear();
  state.savedSelectAll = false;
  ids.forEach(id => state.savedSelected.add(id));
}
function csvPreviewHtml(preview) { const c = preview.counts;
  if (preview.mode === 'new') { const result = `<div class="csv-counts"><span><b>${c.total}</b>Total rows</span><span><b>${c.valid}</b>Valid</span><span><b>${c.existing}</b>Already existing</span><span><b>${c.invalid}</b>Invalid</span></div><p>${c.valid} lead${c.valid === 1 ? '' : 's'} will be created after confirmation.</p>`; const issues = preview.rows.filter(item => item.status === 'invalid' || item.status === 'existing').slice(0, 12); return `${result}${issues.length ? `<ul class="csv-issues">${issues.map(item => `<li>Row ${item.row}: ${escape(item.error || 'Already exists.')}</li>`).join('')}</ul>` : ''}<div class="modal-actions"><button class="button primary" type="button" data-csv-confirm ${!c.valid ? 'disabled' : ''}>Create leads</button></div>`; }
  const cards = [['total', 'TOTAL'], ['foundInLeadManagement', 'FOUND IN LEAD MANAGEMENT'], ['foundInNotUseful', 'FOUND IN NOT USEFUL'], ['foundInBoth', 'FOUND IN BOTH'], ['multipleMatches', 'MULTIPLE MATCHES'], ['notFound', 'NOT FOUND'], ['invalid', 'INVALID']];
  const rows = preview.rows.map(item => `<li class="csv-result-row"><div><b>Row ${item.row}</b><span class="csv-status csv-status-${escape(item.status)}">${csvStatusLabel(item.status)}</span></div>${item.savedLeads?.length ? `<p>Lead Management: ${csvMatchedNames(item.savedLeads)}</p>` : ''}${item.notUsefulLeads?.length ? `<p>Not Useful: ${csvMatchedNames(item.notUsefulLeads)}</p>` : ''}${item.error ? `<p>${escape(item.error)}</p>` : ''}</li>`).join('');
  const selectable = csvMatchedSavedLeadIds(preview).length;
  return `<p class="csv-complete">✓ CSV check complete</p><div class="csv-counts csv-result-counts">${cards.map(([key, label]) => `<span class="csv-count-${key}"><b>${c[key] || 0}</b>${label}</span>`).join('')}</div><p>${selectable} unique eligible Lead Management match${selectable === 1 ? '' : 'es'} can be selected for the existing bulk actions.</p><ol class="csv-results">${rows}</ol><div class="modal-actions"><button class="button secondary" type="button" data-csv-select-matched>Select All Matched</button><button class="button primary" type="button" data-csv-confirm>Continue to bulk actions</button></div>`; }
function csvProcessingHtml(fileName) { return `<div class="csv-processing" role="status"><h3>Checking CSV</h3><p>✓ File loaded: ${escape(fileName)}</p><p>● Checking Lead Management</p><p>● Checking Not Useful</p><p>● Preparing results</p><div class="csv-progress" aria-hidden="true"><span></span></div></div>`; }
function openModal(html) { const modal = $('#outreach-modal'); state.openCampaignId = null; modal.classList.remove('campaign-detail-modal'); $('#outreach-modal-content').innerHTML = html; if (!modal.open) modal.showModal(); }
$('#outreach-modal').addEventListener('click', event => { if (event.target.closest('.modal-close')) $('#outreach-modal').close(); });
$('#outreach-modal').addEventListener('close', () => { state.openCampaignId = null; state.savedNotUsefulConfirmation = null; state.mailboxNotUsefulSummary = null; state.mailboxNotUsefulTarget = null; $('#outreach-modal').classList.remove('campaign-detail-modal'); });
function downloadCsvTemplate(mode) { const existing = mode === 'existing'; const csv = existing ? 'business_name,website,id\r\n' : 'business_name,website,email,country,category\r\n'; const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' }); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = existing ? 'smartlocator-existing-leads-template.csv' : 'smartlocator-new-leads-template.csv'; document.body.append(link); link.click(); link.remove(); setTimeout(() => URL.revokeObjectURL(link.href), 0); }
document.addEventListener('click', async event => { const open = event.target.closest('#import-csv'); if (open) { state.csvImport = { mode: 'new', rows: null, preview: null }; openModal(csvImportModal()); return; } const mode = event.target.closest('[data-csv-mode]'); if (mode) { state.csvImport.requestId = (state.csvImport.requestId || 0) + 1; state.csvImport.mode = mode.dataset.csvMode; state.csvImport.rows = null; state.csvImport.preview = null; state.csvImport.selected = null; document.querySelectorAll('[data-csv-mode]').forEach(button => { button.className = `button ${button === mode ? 'primary' : 'secondary'}`; }); $('#csv-file').value = ''; $('#csv-preview').innerHTML = ''; return; } const retry = event.target.closest('[data-csv-retry]'); if (retry) { $('#csv-file').click(); return; } const template = event.target.closest('[data-csv-template]'); if (template) { downloadCsvTemplate(state.csvImport.mode); return; } const select = event.target.closest('[data-csv-select-matched]'); if (select) { const ids = csvMatchedSavedLeadIds(state.csvImport.preview); state.csvImport.selected = new Set(ids); select.textContent = `Selected ${ids.length} matched`; return; } const confirm = event.target.closest('[data-csv-confirm]'); if (!confirm || !state.csvImport?.preview) return; if (!setButtonLoading(confirm, true, 'Working…')) return; try { if (state.csvImport.mode === 'new') { const result = await api('/api/leads/csv/create', { method: 'POST', body: JSON.stringify({ rows: state.csvImport.rows }) }); $('#outreach-modal').close(); toast(`${result.created} created · ${result.duplicate} duplicate · ${result.invalid} invalid · ${result.failed} failed`); await loadLeads('saved'); } else { const ids = [...(state.csvImport.selected || new Set(csvMatchedSavedLeadIds(state.csvImport.preview)))]; if (!ids.length) throw new Error('Select at least one matched lead.'); replaceSavedLeadSelection(ids); $('#outreach-modal').close(); await loadLeads('saved'); updateSavedSelection(); toast(`${ids.length} matched leads selected. Use the existing bulk actions below.`); } } catch (error) { toast(message(error.message)); } finally { setButtonLoading(confirm, false); } });
document.addEventListener('change', async event => { if (event.target.id !== 'csv-file') return; const file = event.target.files?.[0]; if (!file) return; const csvImport = state.csvImport; if (!csvImport) return; const previewTarget = () => $('#csv-preview'); const showError = error => { const target = previewTarget(); if (target) target.innerHTML = `<div class="csv-check-error"><p class="form-error">Unable to check this CSV.</p><p>${escape(message(error.message))}</p><button class="button secondary" type="button" data-csv-retry>Retry</button></div>`; }; if (!/\.csv$/i.test(file.name) && file.type !== 'text/csv') return showError(new Error('Choose a CSV file.')); if (file.size > 1024 * 1024) return showError(new Error('CSV files must be 1 MB or smaller.')); const requestId = (csvImport.requestId || 0) + 1; csvImport.requestId = requestId; csvImport.rows = null; csvImport.preview = null; csvImport.selected = null; const mode = csvImport.mode; previewTarget().innerHTML = csvProcessingHtml(file.name); try { const rows = parseCsv(await file.text()); if (rows.length > 500) throw new Error('Maximum 500 leads can be processed at once.'); const preview = await api('/api/leads/csv/preview', { method: 'POST', body: JSON.stringify({ mode, rows }) }); if (state.csvImport !== csvImport || csvImport.requestId !== requestId) return; csvImport.rows = rows; csvImport.preview = preview; const target = previewTarget(); if (target) target.innerHTML = `<p class="csv-file-name">${escape(file.name)} · ${Math.ceil(file.size / 1024)} KB</p>${csvPreviewHtml(preview)}`; } catch (error) { if (state.csvImport !== csvImport || csvImport.requestId !== requestId) return; showError(error); } });
function confirmCampaignDelete(id, hasOutreach) { const explanation = hasOutreach ? 'This will remove the campaign and its campaign-specific recipient records. Existing email and WhatsApp outreach history in Lead Management will be preserved.' : 'This will remove this draft campaign and its recipient records.'; openModal(`<h2>Delete this campaign?</h2><p>${explanation}</p><div class="modal-actions"><button class="button secondary" value="cancel">Cancel</button><button class="button danger" type="button" data-confirm-delete-campaign="${id}">Delete campaign</button></div>`); }
function confirmTemplateDelete(id) { openModal(`<h2>Delete this template?</h2><p>This permanently deletes the template. This action cannot be undone.</p><div class="modal-actions"><button class="button secondary" value="cancel">Cancel</button><button class="button danger" type="button" data-confirm-delete-template="${id}">Delete template</button></div>`); }
function confirmSkipRecipient(recipientId, campaignId) { $('#outreach-modal-content').innerHTML = `<h2>Why are you skipping this lead?</h2><label>Reason<select id="skip-reason"><option value="">Select a reason</option>${Object.entries(skipReasonLabels).map(([value, label]) => `<option value="${value}">${escape(label)}</option>`).join('')}</select></label><div class="modal-actions"><button class="button secondary" type="button" data-cancel-skip-recipient data-campaign="${campaignId}">Cancel</button><button class="button primary" type="button" data-confirm-skip-recipient="${recipientId}" data-campaign="${campaignId}">Skip lead</button></div>`; }
function confirmMailboxPermanentDelete(count) { openModal(`<h2>Permanently delete ${count} email${count === 1 ? '' : 's'}?</h2><p>This cannot be undone. Only the selected messages already in Trash will be removed.</p><div class="modal-actions"><button class="button secondary" value="cancel">Cancel</button><button class="button danger" type="button" data-confirm-mailbox-permanent-delete>Delete permanently</button></div>`); }
function confirmMailboxDelete(count) { openModal(`<h2>Move selected emails to Trash?</h2><p>Only the ${count} selected mailbox email${count === 1 ? '' : 's'} will be moved. Campaign delivery and outreach history will not change.</p><div class="modal-actions"><button class="button secondary" value="cancel">Cancel</button><button class="button danger" type="button" data-confirm-mailbox-delete>Move to Trash</button></div>`); }
function templateForm(template = {}) { openModal(`<h2>${template._id ? 'Edit' : 'New'} template</h2><p>Available variables: {{business_name}}, {{website}}, {{email}}, {{phone}}, {{domain}}</p><div class="modal-grid"><label>Name<input id="template-name" maxlength="120" required value="${escape(template.name || '')}"></label><label>Type<select id="template-type"><option value="email" ${template.type !== 'whatsapp' ? 'selected' : ''}>Email</option><option value="whatsapp" ${template.type === 'whatsapp' ? 'selected' : ''}>WhatsApp</option></select></label><label id="template-subject-label">Subject<input id="template-subject" maxlength="200" required value="${escape(template.subject || '')}"></label><label>Message<textarea id="template-body" class="template-text" maxlength="10000" required>${escape(template.body || '')}</textarea></label></div><div class="modal-actions"><button class="button primary" value="default" data-save-template="${template._id || ''}">Save template</button></div>`); }
async function createCampaign(leadIds = []) { if (!state.templates.length) state.templates = (await api('/api/templates')).items; const emails = state.templates.filter(t => t.type === 'email'), whatsapps = state.templates.filter(t => t.type === 'whatsapp'), allMatching = state.savedSelectAll; openModal(`<h2>Create campaign</h2><p>Create a reliable, tracked outreach batch.</p><div class="modal-grid"><label>Campaign name<input id="campaign-name" maxlength="120" required placeholder="Summer Fashion Outreach"></label><label>Channels<select id="campaign-channels"><option value="email">Email</option><option value="whatsapp">WhatsApp</option><option value="both">Email + WhatsApp</option></select></label><label id="campaign-email-provider-field">Email provider<select id="campaign-email-provider" aria-label="Campaign email provider">${emailProviderOptions()}</select></label><label>Email template<select id="campaign-email-template"><option value="">Select template</option>${emails.map(t => `<option value="${t._id}">${escape(t.name)}</option>`).join('')}</select></label><label>WhatsApp template<select id="campaign-whatsapp-template"><option value="">Select template</option>${whatsapps.map(t => `<option value="${t._id}">${escape(t.name)}</option>`).join('')}</select></label><label><input id="include-contacted" type="checkbox"> Include previously contacted businesses</label></div><p>${allMatching ? `${state.savedTotal - state.savedExcluded.size} matching businesses` : `${leadIds.length} selected businesses`} will be read from the database.</p><div class="modal-actions"><button class="button primary" value="default" data-create-campaign data-all-matching="${allMatching}" data-leads="${leadIds.join(',')}">Create campaign</button></div>`); }
async function getCampaignWhatsappMessage(campaignId, recipientId) { const { message: whatsappMessage } = await api(`/api/campaigns/${campaignId}/recipients/${recipientId}/whatsapp-message`); if (typeof whatsappMessage !== 'string' || !whatsappMessage.trim()) throw new Error('WhatsApp message is unavailable'); return whatsappMessage; }
function whatsappPhoneNumber(phone) { const digits = String(phone || '').replace(/\D/g, ''); if (digits.length < 7 || digits.length > 15) throw new Error('WhatsApp phone number is unavailable'); return digits; }
async function openWhatsApp(button) { const popup = window.open('about:blank', '_blank'); try { if (!popup) throw new Error('Your browser blocked WhatsApp. Allow pop-ups and try again.'); const whatsappMessage = await getCampaignWhatsappMessage(button.dataset.campaign, button.dataset.openWhatsapp); const url = `https://wa.me/${whatsappPhoneNumber(button.dataset.phone)}?text=${encodeURIComponent(whatsappMessage)}`; popup.opener = null; popup.location.replace(url); } catch (error) { popup?.close(); throw error; } }
function renderCampaignDetail(id, campaign, items) { const hasEmail = campaign.channels.includes('email'), hasWhatsApp = campaign.channels.includes('whatsapp'); const whatsappActions = row => `<div class="actions"><button class="button secondary" data-copy-whatsapp="${row.whatsapp._id}" data-campaign="${id}" type="button">Copy</button><button class="button secondary" data-open-whatsapp="${row.whatsapp._id}" data-campaign="${id}" data-phone="${escape(row.lead?.phone || '')}" type="button">Open</button><button class="button primary" data-manual-sent="${row.whatsapp._id}" data-campaign="${id}" type="button">Mark sent</button><button class="button secondary" data-skip-recipient="${row.whatsapp._id}" data-campaign="${id}" type="button">Skip</button></div>`; const recipient = row => `<tr><td><b>${escape(row.lead?.businessName || 'Lead')}</b><small>${escape(row.lead?.domain || '')}</small></td>${hasEmail ? `<td><span class="outreach-status status-${commStatus(row.email?.status)}">${escape(emailStatus(row.email))}</span>${row.email?.failureReason ? `<small class="failure-reason">${escape(row.email.failureReason)}</small>` : ''}</td>` : ''}${hasWhatsApp ? `<td><span class="outreach-status status-${commStatus(row.whatsapp?.status)}">${escape(whatsappStatus(row.whatsapp))}</span></td>` : ''}<td>${row.lastContacted ? escape(new Date(row.lastContacted).toLocaleString()) : '—'}</td><td>${hasWhatsApp && row.whatsapp && ['ready', 'pending'].includes(row.whatsapp.status) ? whatsappActions(row) : ''}</td></tr>`; const cards = items.map(row => `<details class="recipient-card"><summary><b>${escape(row.lead?.businessName || 'Lead')}</b><span>${[hasEmail ? emailStatus(row.email) : '', hasWhatsApp ? whatsappStatus(row.whatsapp) : ''].filter(Boolean).join(' · ')}</span></summary><div class="recipient-card-details">${hasEmail ? `<span><b>Email:</b> <span class="outreach-status status-${commStatus(row.email?.status)}">${escape(emailStatus(row.email))}</span></span>${row.email?.failureReason ? `<small class="failure-reason">${escape(row.email.failureReason)}</small>` : ''}` : ''}${hasWhatsApp ? `<span><b>WhatsApp:</b> <span class="outreach-status status-${commStatus(row.whatsapp?.status)}">${escape(whatsappStatus(row.whatsapp))}</span></span>` : ''}<span><b>Last activity:</b> ${row.lastContacted ? escape(new Date(row.lastContacted).toLocaleString()) : '—'}</span>${hasWhatsApp && row.whatsapp && ['ready', 'pending'].includes(row.whatsapp.status) ? whatsappActions(row) : ''}</div></details>`).join(''); return `<section class="campaign-detail-panel"><header><div><p class="eyebrow">Campaign detail</p><h2>${escape(campaign.name)}</h2></div><span class="status-badge">${escape(campaign.status)}</span></header>${campaignMetrics(campaign)}${campaignProgress(campaign)}${hasEmail ? `<div class="modal-actions"><button class="button primary" data-send-campaign="${id}" ${campaign.emailPendingCount ? '' : 'disabled'} type="button">Process next email batch</button>${campaign.emailFailedCount ? `<button class="button secondary" data-retry-failed="${id}" type="button">Retry Failed</button>` : ''}</div>` : ''}<div class="recipient-desktop"><table class="lead-table campaign-detail"><thead><tr><th>Business</th>${hasEmail ? '<th>Email status</th>' : ''}${hasWhatsApp ? '<th>WhatsApp status</th>' : ''}<th>Last contacted</th><th>Actions</th></tr></thead><tbody>${items.map(recipient).join('')}</tbody></table></div><div class="recipient-mobile">${cards}</div></section>`; }
async function refreshOpenCampaign() { const id = state.openCampaignId; if (!id) return; const { campaign, items } = await api(`/api/campaigns/${id}/recipients`); if (state.openCampaignId !== id) return; $('#outreach-modal-content').innerHTML = renderCampaignDetail(id, campaign, items); }
async function openCampaign(id) { state.openCampaignId = id; const modal = $('#outreach-modal'); modal.classList.add('campaign-detail-modal'); await refreshOpenCampaign(); if (state.openCampaignId === id && !modal.open) modal.showModal(); }
document.addEventListener('change', e => { if (e.target.id === 'saved-select-all') { document.querySelectorAll('.saved-lead-select').forEach(box => { if (state.savedSelectAll) { if (e.target.checked) state.savedExcluded.delete(box.dataset.id); else state.savedExcluded.add(box.dataset.id); } else if (e.target.checked) state.savedSelected.add(box.dataset.id); else state.savedSelected.delete(box.dataset.id); }); updateSavedSelection(); } if (e.target.matches('.saved-lead-select')) { if (state.savedSelectAll) { if (e.target.checked) state.savedExcluded.delete(e.target.dataset.id); else state.savedExcluded.add(e.target.dataset.id); } else if (e.target.checked) state.savedSelected.add(e.target.dataset.id); else state.savedSelected.delete(e.target.dataset.id); updateSavedSelection(); } if (e.target.id === 'template-type') $('#template-subject-label').hidden = e.target.value === 'whatsapp'; });
document.addEventListener('change', event => { if (event.target.id === 'campaign-channels') { const provider = $('#campaign-email-provider-field'); if (provider) provider.hidden = event.target.value === 'whatsapp'; } });

document.addEventListener('click', async e => { try { const cancelSkip = e.target.closest('[data-cancel-skip-recipient]'); if (cancelSkip) return openCampaign(cancelSkip.dataset.campaign); if (e.target.id === 'saved-filter-toggle') { const panel = $('#saved-filter-panel'); panel.hidden = !panel.hidden; e.target.setAttribute('aria-expanded', String(!panel.hidden)); return; } if (e.target.closest('#saved-filter-close')) { $('#saved-filter-panel').hidden = true; $('#saved-filter-toggle').setAttribute('aria-expanded', 'false'); $('#saved-filter-toggle').focus(); return; } if (e.target.id === 'saved-select-matching') { state.savedSelected.clear(); state.savedExcluded.clear(); state.savedSelectAll = true; updateSavedSelection(); return; } if (e.target.closest('[data-open-template]')) return templateForm(); if (e.target.closest('[data-open-campaign]')) return createCampaign(); if (e.target.id === 'add-to-campaign') { const button = e.target; if (!setButtonLoading(button, true, 'Adding…')) return; try { return await createCampaign([...state.savedSelected]); } finally { setButtonLoading(button, false); } } if (e.target.id === 'mark-saved-not-useful') return confirmMarkSavedNotUseful(); const confirmSavedNotUseful = e.target.closest('[data-confirm-saved-not-useful]'); if (confirmSavedNotUseful) return markSavedNotUseful(confirmSavedNotUseful); const one = e.target.closest('[data-add-one-campaign]'); if (one) { if (!setButtonLoading(one, true, 'Adding…')) return; try { return await createCampaign([one.dataset.addOneCampaign]); } finally { setButtonLoading(one, false); } } const edit = e.target.closest('[data-edit-template]'); if (edit) return templateForm(state.templates.find(t => t._id === edit.dataset.editTemplate)); const duplicate = e.target.closest('[data-duplicate-template]'); if (duplicate) { const copy = state.templates.find(t => t._id === duplicate.dataset.duplicateTemplate); return templateForm({ ...copy, _id: null, name: `${copy.name} copy` }); } const del = e.target.closest('[data-delete-template]'); if (del) return confirmTemplateDelete(del.dataset.deleteTemplate); const confirmDeleteTemplate = e.target.closest('[data-confirm-delete-template]'); if (confirmDeleteTemplate) { if (!setButtonLoading(confirmDeleteTemplate, true, 'Deleting…')) return; try { await api(`/api/templates/${confirmDeleteTemplate.dataset.confirmDeleteTemplate}`, { method: 'DELETE' }); $('#outreach-modal').close(); toast('Deleted successfully'); return loadTemplates(); } finally { setButtonLoading(confirmDeleteTemplate, false); } } const save = e.target.closest('[data-save-template]'); if (save) { const type = $('#template-type').value; const fields = [$('#template-name'), $('#template-body')]; if (type === 'email') fields.splice(1, 0, $('#template-subject')); if (!validateFields(fields)) return; const creating = !save.dataset.saveTemplate; if (!setButtonLoading(save, true, creating ? 'Creating…' : 'Saving…')) return; try { await api(save.dataset.saveTemplate ? `/api/templates/${save.dataset.saveTemplate}` : '/api/templates', { method: save.dataset.saveTemplate ? 'PATCH' : 'POST', body: JSON.stringify({ name: $('#template-name').value, type, subject: $('#template-subject').value, body: $('#template-body').value }) }); $('#outreach-modal').close(); toast(creating ? 'Template created successfully' : 'Template saved successfully'); return loadTemplates(); } finally { setButtonLoading(save, false); } } const create = e.target.closest('[data-create-campaign]'); if (create) { const channels = $('#campaign-channels').value === 'both' ? ['email', 'whatsapp'] : [$('#campaign-channels').value]; const fields = [$('#campaign-name')]; if (channels.includes('email')) fields.push($('#campaign-email-template')); if (channels.includes('whatsapp')) fields.push($('#campaign-whatsapp-template')); if (!validateFields(fields)) return; if (!setButtonLoading(create, true, 'Creating…')) return; try { const campaign = await api('/api/campaigns', { method: 'POST', body: JSON.stringify({ name: $('#campaign-name').value, channels, emailProvider: $('#campaign-email-provider').value, emailTemplateId: $('#campaign-email-template').value, whatsappTemplateId: $('#campaign-whatsapp-template').value }) }); const body = create.dataset.allMatching === 'true' ? { selectAllMatching: true, ...state.filters.saved, excludedLeadIds: [...state.savedExcluded], includeContacted: $('#include-contacted').checked } : { leadIds: create.dataset.leads.split(',').filter(Boolean), includeContacted: $('#include-contacted').checked }; await api(`/api/campaigns/${campaign._id}/recipients`, { method: 'POST', body: JSON.stringify(body) }); state.savedSelected.clear(); state.savedExcluded.clear(); state.savedSelectAll = false; updateSavedSelection(); $('#outreach-modal').close(); toast('Campaign created successfully'); location.hash = 'campaigns'; return; } finally { setButtonLoading(create, false); } } const removeCampaign = e.target.closest('[data-delete-campaign]'); if (removeCampaign) return confirmCampaignDelete(removeCampaign.dataset.deleteCampaign, removeCampaign.dataset.hasOutreach === 'true'); const confirmDeleteCampaign = e.target.closest('[data-confirm-delete-campaign]'); if (confirmDeleteCampaign) { confirmDeleteCampaign.disabled = true; await api(`/api/campaigns/${confirmDeleteCampaign.dataset.confirmDeleteCampaign}`, { method: 'DELETE' }); $('#outreach-modal').close(); toast('Campaign deleted'); await loadCampaigns(); return populateCampaignFilter(); } const open = e.target.closest('[data-open-campaign-detail]'); if (open) return openCampaign(open.dataset.openCampaignDetail); const send = e.target.closest('[data-send-campaign], [data-retry-failed]'); if (send) { if (state.sendingCampaign || !setButtonLoading(send, true, send.dataset.retryFailed ? 'Retrying…' : 'Sending…')) return; state.sendingCampaign = true; try { const result = await api(`/api/campaigns/${send.dataset.sendCampaign || send.dataset.retryFailed}/${send.dataset.retryFailed ? 'retry-failed' : 'send'}`, { method: 'POST' }); toast(result.failed ? (result.sent ? `Batch sent to ${result.sent}; ${result.failed} failed.` : `Batch failed: ${result.failed} recipient${result.failed === 1 ? '' : 's'}.`) : `Batch sent to ${result.sent} recipient${result.sent === 1 ? '' : 's'}.`); await loadCampaigns(); return refreshOpenCampaign(); } finally { state.sendingCampaign = false; setButtonLoading(send, false); } } const manual = e.target.closest('[data-manual-sent]'); if (manual) { if (!setButtonLoading(manual, true, 'Marking…')) return; try { await api(`/api/campaigns/${manual.dataset.campaign}/recipients/${manual.dataset.manualSent}/manual-sent`, { method: 'POST' }); toast('WhatsApp marked as manually sent'); await loadCampaigns(); return refreshOpenCampaign(); } finally { setButtonLoading(manual, false); } } const skip = e.target.closest('[data-skip-recipient]'); if (skip) return confirmSkipRecipient(skip.dataset.skipRecipient, skip.dataset.campaign); const confirmSkip = e.target.closest('[data-confirm-skip-recipient]'); if (confirmSkip) { const skipReason = $('#skip-reason').value; if (!skipReason) { $('#skip-reason').setCustomValidity('Choose a skip reason.'); $('#skip-reason').reportValidity(); return; } if (!setButtonLoading(confirmSkip, true, 'Skipping…')) return; try { await api(`/api/campaigns/${confirmSkip.dataset.campaign}/recipients/${confirmSkip.dataset.confirmSkipRecipient}/skip`, { method: 'POST', body: JSON.stringify({ skipReason }) }); await loadCampaigns(); return refreshOpenCampaign(); } finally { setButtonLoading(confirmSkip, false); } } const openWhatsapp = e.target.closest('[data-open-whatsapp]'); if (openWhatsapp) return openWhatsApp(openWhatsapp); const copy = e.target.closest('[data-copy-whatsapp]'); if (copy) { await navigator.clipboard.writeText(await getCampaignWhatsappMessage(copy.dataset.campaign, copy.dataset.copyWhatsapp)); toast('Message copied'); } } catch (error) { toast(message(error.message)); } });


// Ready for future outreach

document.addEventListener('click', async event => {
  const mailboxTab = event.target.closest('[data-mailbox-box]'); if (mailboxTab) { state.mailboxBox = mailboxTab.dataset.mailboxBox; state.mailboxPage = 1; state.mailboxSelected.clear(); document.querySelectorAll('[data-mailbox-box]').forEach(button => { const selected = button === mailboxTab; button.classList.toggle('active', selected); button.setAttribute('aria-selected', String(selected)); button.tabIndex = selected ? 0 : -1; }); return loadMailbox(); }
  const mailboxPage = event.target.closest('[data-mailbox-page]'); if (mailboxPage) { state.mailboxPage = Number(mailboxPage.dataset.mailboxPage); state.mailboxSelected.clear(); return loadMailbox(); }
  if (event.target.closest('[data-retry-mailbox]')) return loadMailbox();
  if (event.target.closest('[data-retry-conversation]')) { const retry = event.target.closest('[data-retry-conversation]'); return openMailConversation(retry.dataset.retryConversation, retry.hasAttribute('data-retry-trash-conversation')); }
  if (event.target.id === 'mailbox-delete-selected') { if (state.mailboxSelected.size) confirmMailboxDelete(state.mailboxSelected.size); return; }
  if (event.target.id === 'mailbox-mark-not-useful') return checkMailboxNotUseful();
  if (event.target.closest('[data-retry-mailbox-not-useful]')) return checkMailboxNotUseful();
  const markMailboxNotUsefulButton = event.target.closest('[data-confirm-mailbox-not-useful]'); if (markMailboxNotUsefulButton) return markMailboxNotUseful(markMailboxNotUsefulButton);
  if (event.target.id === 'mailbox-restore-selected') { if (!state.mailboxSelected.size) return; await api('/api/mailbox/messages/restore', { method: 'POST', body: JSON.stringify({ ids: [...state.mailboxSelected] }) }); state.mailboxSelected.clear(); toast('Selected emails restored'); await loadMailbox(); return loadMailboxCounts(); }
  if (event.target.id === 'mailbox-permanent-delete-selected') { if (state.mailboxSelected.size) confirmMailboxPermanentDelete(state.mailboxSelected.size); return; }
  const permanentMail = event.target.closest('[data-confirm-mailbox-permanent-delete]'); if (permanentMail) { if (!setButtonLoading(permanentMail, true, 'Deleting…')) return; try { await api('/api/mailbox/messages/permanent-delete', { method: 'POST', body: JSON.stringify({ ids: [...state.mailboxSelected], confirmation: 'DELETE' }) }); state.mailboxSelected.clear(); $('#outreach-modal').close(); toast('Selected emails permanently deleted'); await loadMailbox(); return loadMailboxCounts(); } finally { setButtonLoading(permanentMail, false); } }
  const deleteSelected = event.target.closest('[data-confirm-mailbox-delete]'); if (deleteSelected) { if (!setButtonLoading(deleteSelected, true, 'Deleting…')) return; try { await api('/api/mailbox/messages/delete', { method: 'POST', body: JSON.stringify({ ids: [...state.mailboxSelected], confirmation: 'DELETE' }) }); state.mailboxSelected.clear(); $('#outreach-modal').close(); toast('Selected emails moved to Trash'); await loadMailbox(); return loadMailboxCounts(); } finally { setButtonLoading(deleteSelected, false); } }
  if (event.target.id === 'mailbox-compose') return mailboxComposer();
  const openMail = event.target.closest('[data-open-mail]'); if (openMail) return openMailConversation(openMail.dataset.openMail, openMail.hasAttribute('data-open-trash-mail'));
  const reply = event.target.closest('[data-mail-reply]'); if (reply) return mailboxComposer(reply.dataset.mailReply, { to: reply.dataset.mailTo, subject: reply.dataset.mailSubject });
  const sendMail = event.target.closest('[data-mail-send]'); if (sendMail) { const to = emailAddresses($('#mail-to'), true), cc = emailAddresses($('#mail-cc')), bcc = emailAddresses($('#mail-bcc')); if (!to || !cc || !bcc || !validateFields([$('#mail-subject'), $('#mail-text')])) return; if (!setButtonLoading(sendMail, true, 'Sending…')) return; try { const body = { to, cc, bcc, subject: $('#mail-subject').value, text: $('#mail-text').value, ...(sendMail.dataset.mailSend ? {} : { emailProvider: $('#mail-email-provider').value }) }; await api(sendMail.dataset.mailSend ? `/api/mailbox/conversations/${encodeURIComponent(sendMail.dataset.mailSend)}/reply` : '/api/mailbox/send', { method: 'POST', body: JSON.stringify(body) }); $('#outreach-modal').close(); toast('Email sent'); await loadMailbox(); return loadMailboxCounts(); } finally { setButtonLoading(sendMail, false); } }
  const deleteMail = event.target.closest('[data-mail-delete]'); if (deleteMail) { if (!setButtonLoading(deleteMail, true, 'Deleting…')) return; try { await api(`/api/mailbox/conversations/${encodeURIComponent(deleteMail.dataset.mailDelete)}/delete`, { method: 'PATCH', body: JSON.stringify({}) }); $('#outreach-modal').close(); toast('Conversation moved to Trash'); await loadMailbox(); return loadMailboxCounts(); } finally { setButtonLoading(deleteMail, false); } }
  if (event.target.closest('[data-close-modal]')) return $('#outreach-modal').close();
  const tab = event.target.closest('[data-lead-tab]');
  if (tab) { state.leadTab = tab.dataset.leadTab; document.querySelectorAll('[data-lead-tab]').forEach(button => { const selected = button === tab; button.classList.toggle('active', selected); button.setAttribute('aria-selected', String(selected)); button.tabIndex = selected ? 0 : -1; }); state.savedSelected.clear(); state.savedExcluded.clear(); state.savedSelectAll = false; state.pages.saved = 1; return loadLeads('saved'); }
  if (event.target.closest('#add-manual-lead')) { openModal(`<h2>Add saved lead</h2><p>This adds a business directly to Lead Management; it will not be added to a campaign.</p><div class="modal-grid"><label>Business name<input id="manual-business" maxlength="200" required></label><label>Website<input id="manual-website" type="url" maxlength="500" placeholder="https://example.com" required></label><label>Email<input id="manual-email" maxlength="254" type="email" required></label><label>Phone<input id="manual-phone" maxlength="80" type="tel"></label><label>Category<input id="manual-category" maxlength="100"></label><label>Location<input id="manual-location" maxlength="100"></label><label>Notes<textarea id="manual-notes" maxlength="2000"></textarea></label></div><p>Website and email are required. Phone is optional.</p><div class="modal-actions"><button class="button primary" type="button" id="save-manual-lead">Save lead</button></div>`); return; }
  const saveLead = event.target.closest('#save-manual-lead'); if (saveLead) { if (!validateFields([$('#manual-business'), $('#manual-website'), $('#manual-email')])) return; if (!setButtonLoading(saveLead, true, 'Saving…')) return; try { await api('/api/leads/manual', { method: 'POST', body: JSON.stringify({ businessName: $('#manual-business').value, website: $('#manual-website').value, email: $('#manual-email').value, phone: $('#manual-phone').value, category: $('#manual-category').value, location: $('#manual-location').value, notes: $('#manual-notes').value }) }); $('#outreach-modal').close(); toast('Lead added successfully'); return loadLeads('saved'); } catch (error) { toast(message(error.message)); } finally { setButtonLoading(saveLead, false); } }
});
async function populateCampaignFilter() { try { const campaigns = (await api('/api/campaigns')).items; const select = $('#saved-campaign'); const current = select.value; select.innerHTML = `<option value="">All campaigns</option>${campaigns.map(c => `<option value="${c._id}">${escape(c.name)}</option>`).join('')}`; select.value = current; } catch { /* Lead management remains usable without campaign filter options. */ } }

document.addEventListener('keydown', event => { const tab = event.target.closest('[data-lead-tab]'); if (!tab || !['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return; const tabs = [...document.querySelectorAll('[data-lead-tab]')]; let i = tabs.indexOf(tab); i = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : (i + (event.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length; event.preventDefault(); tabs[i].focus(); tabs[i].click(); });
document.querySelectorAll('#sign-out, #mobile-sign-out').forEach(button => button.addEventListener('click', async () => { if (button.disabled) return; button.disabled = true; try { await fetch('/api/auth/logout', { method: 'POST', headers: { 'Content-Type': 'application/json' } }); } finally { window.location.assign('/login'); } }));
